@section('page-script')<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('provision-form'),slug=document.getElementById('slug'),create=document.getElementById('create'),checks=document.getElementById('checks'),existing=document.getElementById('existing-client-field'),fresh=document.getElementById('new-client-field'),clientId=document.getElementById('client-id'),clientName=document.getElementById('new-client-name');function mode(){const isExisting=document.querySelector('[name="client_mode"]:checked').value==='existing';existing.classList.toggle('d-none',!isExisting);fresh.classList.toggle('d-none',isExisting);clientId.disabled=!isExisting;clientName.disabled=isExisting;checks.innerHTML='';create.disabled=true}document.querySelectorAll('[name="client_mode"]').forEach(el=>el.addEventListener('change',mode));mode();slug.addEventListener('input',()=>{document.getElementById('folder').textContent=@json(rtrim(config('ikontrol.instances_root'),'/\\').'/')+slug.value+@json(config('ikontrol.folder_suffix'));document.getElementById('database').textContent=@json(config('ikontrol.db.prefix'))+slug.value;checks.innerHTML='';create.disabled=true});document.getElementById('preflight').addEventListener('click',async()=>{const response=await fetch(@json(route('provisioning.preflight')),{method:'POST',headers:{Accept:'application/json'},body:new FormData(form)});const result=await response.json();if(!response.ok){checks.innerHTML='<div class="alert alert-danger">Revise los campos requeridos.</div>';return}const labels={slug_valid:'Slug válido',folder_available:'Carpeta disponible',filesystem_writable:'Filesystem escribible',cpanel_connected:'cPanel conectado',database_not_existing:'Base no existente',mysql_user_available:'Usuario MySQL disponible'};checks.innerHTML='<div class="alert alert-'+(result.success?'success':'warning')+'">'+Object.entries(result.checks).map(([key,value])=>`<div class="d-flex align-items-center gap-2 mb-1"><i class="icon-base ti ${value?'tabler-circle-check text-success':'tabler-circle-x text-danger'}"></i>${labels[key]||key}</div>`).join('')+'</div>';create.disabled=!result.success})})</script>@endsection
